package me.kright.gametools.pga3d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer
import me.kright.gametools.mathutil.CanEqualWithEps


/**
 * A plane ax + by + cz + d = 0 with the coefficients (a, b, c, d) stored in the fields (x, y, z, w);
 * the grade-1 element of 3d PGA.
 *
 * Variable fields: x, y, z, w.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga3d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga3dPlane(x: Double = 0.0,
                            y: Double = 0.0,
                            z: Double = 0.0,
                            w: Double = 0.0) derives CanEqual, CanEqualWithEps, FlatDoubleSerializer:

  override def toString: String =
    s"Pga3dPlane(x = $x, y = $y, z = $z, w = $w)"

  def dual: Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = x,
      y = y,
      z = z,
      w = w,
    )

  def weight: Pga3dPlane =
    Pga3dPlane(
      x = 0.0,
      y = 0.0,
      z = 0.0,
      w = w,
    )

  def bulk: Pga3dPlaneCentral =
    Pga3dPlaneCentral(
      x = x,
      y = y,
      z = z,
    )

  @targetName("unaryMinus")
  def unary_- : Pga3dPlane =
    Pga3dPlane(
      x = -x,
      y = -y,
      z = -z,
      w = -w,
    )

  def reverse: Pga3dPlane =
    this

  def antiReverse: Pga3dPlane =
    -this

  def bulkNormSquare: Double =
    (x * x + y * y + z * z)

  def bulkNorm: Double =
    Math.sqrt(bulkNormSquare)

  def normalizedByBulk =
    this / bulkNorm

  def weightNormSquare: Double =
    w * w

  def weightNorm: Double =
    Math.sqrt(weightNormSquare)

  def normalizedByWeight =
    this / weightNorm

  def normSquare: Double =
    ((w * w + x * x) + (y * y + z * z))

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga3dPlane =
    Pga3dPlane(
      x = r * x,
      y = r * y,
      z = r * z,
      w = r * w,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga3dPlane =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga3dPlane): Pga3dPlane =
    Pga3dPlane(
      x = (r.x + x),
      y = (r.y + y),
      z = (r.z + z),
      w = (r.w + w),
    )

  @targetName("minus")
  def -(r: Pga3dPlane): Pga3dPlane =
    Pga3dPlane(
      x = (x - r.x),
      y = (y - r.y),
      z = (z - r.z),
      w = (w - r.w),
    )

  def madd(r: Pga3dPlane, mult: Double): Pga3dPlane =
    Pga3dPlane(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      z = (z + mult * r.z),
      w = (w + mult * r.w),
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga3dPlane): Pga3dPlane =
    Pga3dPlane(
      x = x * r.x,
      y = y * r.y,
      z = z * r.z,
      w = w * r.w,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga3dPlane =
    Pga3dPlane(
      x = 1.0 / x,
      y = 1.0 / y,
      z = 1.0 / z,
      w = 1.0 / w,
    )

  def toMultivector: Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = w,
      x = x,
      y = y,
      z = z,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = 0.0,
      wxz = 0.0,
      wyz = 0.0,
      xyz = 0.0,
      i = 0.0,
    )

  def toPlaneCentralUnsafe: Pga3dPlaneCentral =
    Pga3dPlaneCentral(
      x = x,
      y = y,
      z = z,
    )

  infix def geometric(r: Pga3dMotor): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = ((r.s * w - r.wx * x) - (r.wy * y + r.wz * z)),
      x = (r.s * x - r.xy * y - r.xz * z),
      y = (r.s * y + r.xy * x - r.yz * z),
      z = (r.s * z + r.xz * x + r.yz * y),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = ((r.wx * y + r.xy * w) - (r.i * z + r.wy * x)),
      wxz = ((r.i * y + r.wx * z) + (r.xz * w - r.wz * x)),
      wyz = ((r.wy * z + r.yz * w) - (r.i * x + r.wz * y)),
      xyz = (r.xy * z + r.yz * x - r.xz * y),
      i = 0.0,
    )

  infix def geometric(r: Pga3dPlane): Pga3dMotor =
    Pga3dMotor(
      s = (r.x * x + r.y * y + r.z * z),
      wx = (r.x * w - r.w * x),
      wy = (r.y * w - r.w * y),
      wz = (r.z * w - r.w * z),
      xy = (r.y * x - r.x * y),
      xz = (r.z * x - r.x * z),
      yz = (r.z * y - r.y * z),
      i = 0.0,
    )

  infix def geometric(r: Pga3dBivector): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (-r.wx * x - r.wy * y - r.wz * z),
      x = (-r.xy * y - r.xz * z),
      y = (r.xy * x - r.yz * z),
      z = (r.xz * x + r.yz * y),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.wx * y + r.xy * w - r.wy * x),
      wxz = (r.wx * z + r.xz * w - r.wz * x),
      wyz = (r.wy * z + r.yz * w - r.wz * y),
      xyz = (r.xy * z + r.yz * x - r.xz * y),
      i = 0.0,
    )

  infix def geometric(r: Pga3dProjectivePoint): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = (r.y * z - r.z * y),
      wy = (r.z * x - r.x * z),
      wz = (r.x * y - r.y * x),
      xy = r.w * z,
      xz = -r.w * y,
      yz = r.w * x,
      i = ((r.w * w + r.x * x) + (r.y * y + r.z * z)),
    )

  infix def geometric(r: Pga3dRotor): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = r.s * w,
      x = (r.s * x - r.xy * y - r.xz * z),
      y = (r.s * y + r.xy * x - r.yz * z),
      z = (r.s * z + r.xz * x + r.yz * y),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = r.xy * w,
      wxz = r.xz * w,
      wyz = r.yz * w,
      xyz = (r.xy * z + r.yz * x - r.xz * y),
      i = 0.0,
    )

  infix def geometric(r: Pga3dProjectiveTranslator): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = ((r.s * w - r.wx * x) - (r.wy * y + r.wz * z)),
      x = r.s * x,
      y = r.s * y,
      z = r.s * z,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.wx * y - r.wy * x),
      wxz = (r.wx * z - r.wz * x),
      wyz = (r.wy * z - r.wz * y),
      xyz = 0.0,
      i = 0.0,
    )

  infix def geometric(r: Pga3dTranslator): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = ((w - r.wx * x) - (r.wy * y + r.wz * z)),
      x = x,
      y = y,
      z = z,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.wx * y - r.wy * x),
      wxz = (r.wx * z - r.wz * x),
      wyz = (r.wy * z - r.wz * y),
      xyz = 0.0,
      i = 0.0,
    )

  infix def geometric(r: Pga3dVector): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = (r.y * z - r.z * y),
      wy = (r.z * x - r.x * z),
      wz = (r.x * y - r.y * x),
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      i = (r.x * x + r.y * y + r.z * z),
    )

  infix def geometric(r: Pga3dPoint): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = (r.y * z - r.z * y),
      wy = (r.z * x - r.x * z),
      wz = (r.x * y - r.y * x),
      xy = z,
      xz = -y,
      yz = x,
      i = ((w + r.x * x) + (r.y * y + r.z * z)),
