  infix def geometric(r: Pga3dPlaneCentral): Pga3dMotor =
    Pga3dMotor(
      s = (r.x * x + r.y * y + r.z * z),
      wx = r.x * w,
      wy = r.y * w,
      wz = r.z * w,
      xy = (r.y * x - r.x * y),
      xz = (r.z * x - r.x * z),
      yz = (r.z * y - r.y * z),
      i = 0.0,
    )

  infix def geometric(r: Pga3dBivectorBulk): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = 0.0,
      x = (-r.xy * y - r.xz * z),
      y = (r.xy * x - r.yz * z),
      z = (r.xz * x + r.yz * y),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = r.xy * w,
      wxz = r.xz * w,
      wyz = r.yz * w,
      xyz = (r.xy * z + r.yz * x - r.xz * y),
      i = 0.0,
    )

  infix def geometric(r: Pga3dBivectorWeight): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (-r.wx * x - r.wy * y - r.wz * z),
      x = 0.0,
      y = 0.0,
      z = 0.0,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.wx * y - r.wy * x),
      wxz = (r.wx * z - r.wz * x),
      wyz = (r.wy * z - r.wz * y),
      xyz = 0.0,
      i = 0.0,
    )

  infix def geometric(r: Pga3dPseudoScalar): Pga3dVector =
    Pga3dVector(
      x = r.i * x,
      y = r.i * y,
      z = r.i * z,
    )

  infix def geometric(r: Pga3dPointCenter.type): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = z,
      xz = -y,
      yz = x,
      i = w,
    )

  infix def dot(r: Pga3dMotor): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = ((r.s * w - r.wx * x) - (r.wy * y + r.wz * z)),
      x = (r.s * x - r.xy * y - r.xz * z),
      y = (r.s * y + r.xy * x - r.yz * z),
      z = (r.s * z + r.xz * x + r.yz * y),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = -r.i * z,
      wxz = r.i * y,
      wyz = -r.i * x,
      xyz = 0.0,
      i = 0.0,
    )

  infix def dot(r: Pga3dPlane): Double =
    (r.x * x + r.y * y + r.z * z)

  infix def dot(r: Pga3dBivector): Pga3dPlane =
    Pga3dPlane(
      x = (-r.xy * y - r.xz * z),
      y = (r.xy * x - r.yz * z),
      z = (r.xz * x + r.yz * y),
      w = (-r.wx * x - r.wy * y - r.wz * z),
    )

  infix def dot(r: Pga3dProjectivePoint): Pga3dBivector =
    Pga3dBivector(
      wx = (r.y * z - r.z * y),
      wy = (r.z * x - r.x * z),
      wz = (r.x * y - r.y * x),
      xy = r.w * z,
      xz = -r.w * y,
      yz = r.w * x,
    )

  infix def dot(r: Pga3dRotor): Pga3dPlane =
    Pga3dPlane(
      x = (r.s * x - r.xy * y - r.xz * z),
      y = (r.s * y + r.xy * x - r.yz * z),
      z = (r.s * z + r.xz * x + r.yz * y),
      w = r.s * w,
    )

  infix def dot(r: Pga3dProjectiveTranslator): Pga3dPlane =
    Pga3dPlane(
      x = r.s * x,
      y = r.s * y,
      z = r.s * z,
      w = ((r.s * w - r.wx * x) - (r.wy * y + r.wz * z)),
