  infix def dot(r: Pga3dTranslator): Pga3dPlane =
    Pga3dPlane(
      x = x,
      y = y,
      z = z,
      w = ((w - r.wx * x) - (r.wy * y + r.wz * z)),
    )

  infix def dot(r: Pga3dVector): Pga3dBivectorWeight =
