  infix def dot(r: Pga3dPlaneCentral): Double =
    (r.x * x + r.y * y + r.z * z)

  infix def dot(r: Pga3dBivectorBulk): Pga3dPlaneCentral =
    Pga3dPlaneCentral(
      x = (-r.xy * y - r.xz * z),
      y = (r.xy * x - r.yz * z),
      z = (r.xz * x + r.yz * y),
