      x = r.s * x,
      y = r.s * y,
      z = r.s * z,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.wx * y - r.wy * x),
      wxz = (r.wx * z - r.wz * x),
      wyz = (r.wy * z - r.wz * y),
      xyz = 0.0,
      i = 0.0,
    )

  inline infix def ^(r: Pga3dProjectiveTranslator): Pga3dMultivector = wedge(r)

  inline infix def meet(r: Pga3dProjectiveTranslator): Pga3dMultivector = wedge(r)

  infix def wedge(r: Pga3dTranslator): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = w,
      x = x,
      y = y,
      z = z,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.wx * y - r.wy * x),
      wxz = (r.wx * z - r.wz * x),
      wyz = (r.wy * z - r.wz * y),
