  inline infix def ^(r: Pga3dTranslator): Pga3dMultivector = wedge(r)

  inline infix def meet(r: Pga3dTranslator): Pga3dMultivector = wedge(r)

  infix def wedge(r: Pga3dVector): Pga3dPseudoScalar =
    Pga3dPseudoScalar(
