  inline infix def ^(r: Pga3dVector): Pga3dPseudoScalar = wedge(r)

  inline infix def meet(r: Pga3dVector): Pga3dPseudoScalar = wedge(r)

  infix def wedge(r: Pga3dPoint): Pga3dPseudoScalar =
    Pga3dPseudoScalar(
